```js
// src/season.js
export const MOVE_PRICE=15;
export const levelOf=why=>{const p=Math.floor(why.confidence*100);return p>=Math.round(CONFIDENT*100)?'CONFIDENT':p>=Math.round(DOUBTFUL*100)?'MODERATE':'DOUBTFUL';};
// The package to make now: not doubtful, not costing the season, within the transfers left. A smaller package wins
// only when each move it saves would add less than `price` FP over the horizon AND over the season; when transfers
// are free (pre-season) nothing is saved, so price is 0.
export function recommendPackage(ctx,{team,bankMoney,left,sort='month',price=MOVE_PRICE}){
 const options=[];let previous=0;
 for(const k of [1,2,3]){const p=bestPackage(ctx,{team,bankMoney,k,sort});if(!p||!p.pairs.length||p.gain<=previous+1e-6)continue;previous=p.gain;
  const why=explainSwap(ctx,null,null,sort,p.pairs.map(x=>[x.out.id,x.in.id]));options.push({...p,why,lvl:levelOf(why)});}
 const fits=options.filter(o=>o.lvl!=='DOUBTFUL'&&o.gains.season>=0&&o.pairs.length<=left&&o.gains[sort]>0).sort((a,b)=>b.gains[sort]-a.gains[sort]);
 let best=fits[0]||null;
 for(const f of fits){const d=best?best.pairs.length-f.pairs.length:0;
  if(d>0&&best.gains[sort]-f.gains[sort]<price*d&&best.gains.season-f.gains.season<price*d)best=f;}
 return {best,options};
}
```
