def external_check(rows_by_season, history, xwalk):
    nba = {str(p['sportsId']): p.get('nbaId') for p in xwalk['players']}
    res, nob = [], []
    for year, raw in rows_by_season.items():
        rows, _ = normalize_minutes(raw, year)
        pts = defaultdict(int); teams = defaultdict(set)
        for r in raw: pts[(r['game_id'], r['team'])] += r['pts']; teams[r['game_id']].add(r['team'])
